    "studio_note": null,
    "notes": "Had a tabla teacher called Masterji who had paan breath and was harsh in his teaching method. Masterji was eventually replaced by a two-headed stuffed monkey-a gift that superseded the teacher entirely. Masterji never returned. The replacement of a person with an object speaks to young Raghava's early strategic thinking: rather than fight an authority that is unhelpful, find a way to make them irrelevant. The two-headed monkey-absurdist, surreal, paradoxical-suggests that Raghava needed teachers who could hold contradiction and complexity, not rigid discipline. This is the first instance of Raghava using strategy to navigate authority.",
