    "studio_note": null,
    "notes": "Naseer lived behind the bungalow in servants' quarters, separated by a shared wall from the main house. No memory of how they met-just suddenly inseparable. The trio became Raghava, Kaesava, and Naseer. But Naseer was 'the new twin'-closer than the biological twin, who was starting to be sidelined by this point. Naseer got access to Raghava's world: Johnson Market, five-star treatment, food, social standing he couldn't have otherwise. They slept together, bathed together, played together. The relationship was intimate at a physical level that later life doesn't easily accommodate. Mother's warning was prescient: 'You cannot show him a life he cannot live. That is not fair.' Raghava ignored her.\n\nNaseer disappears in 1998 (morning of Black Cadillac). Promise never to see him again made at age 17.",
