    "verified_by": null,
    "verified_date": null,
    "essence": "Father's conditional seeing; son as redemption project",
    "key_points": [],
    "process_notes": null,
    "truth_correction": null,
    "psychological_note": null,
    "studio_note": null,
    "notes": "Mrs. Sandhya Raman said one twin must fail and repeat algebra. Father got an algebra book (Hall and Knight or similar). Taught Raghava every day that summer. Raghava discovered he was brilliant at math. Father said: 'He sees greatness in me. That he's never seen it in any human being.' But this was projection: 'I see greatness IN YOU' not 'I'm proud of you.' Son as father's redemption. The love was about what Raghava could confirm about the father, not about Raghava himself. Saturday mornings he appeared. Games. Storytelling. When he was present, Raghava felt 'alive.' But most of the time: absent. Never asked what grade Raghava was in. Never consoled him. Occasional 'I love you' rare enough to feel enormous.\n\nFOUNDATIONAL PATTERN: Father's love is conditional on Raghava's performance of greatness. Father uses son as mirror to see his own potential. This is the core wound.",
    "people": [
      {
        "name": "Mrs. Sandhya Raman",
        "role": "teacher"
      }
    ],
