    "psychological_note": null,
    "studio_note": null,
    "notes": "At age 16 (1996), declared to father 'From today I will be different'-pledging discipline and curiosity, seeing himself as transformed. In 1999, formally quit education after joining Chitrakala Parishad and art school rejections. During this journey: rejected by NID (questions felt ridiculous, 'they didn't feel me'); admitted to Srishti but advised by founder not to join (school too new); didn't apply to American schools (fear of rejection, parents couldn't afford, mother very sick); joined Chitrakala Parishad instead; faced immediate bullying by peer artists who already knew him; girl there was obsessed with him; called mother in emotional crisis. Mother told him: 'If you don't love what you're doing and they're taking the love for art away from you, quit.' He quit. Made promise to parents: will build own curriculum, learn from the world.\n\nMerged three related entries about education departure; conflict resolved by MASTER_CANON confirmation of 1999 date.",
