    "studio_note": null,
    "notes": "The group formed through Madhyam organization and cartoonist Panapa's Times of India workshop. Karthik saw the advertisement and signed Raghava up. Members included: Samitha Rathore (sophisticated, dating lead singer of Millennium band), Rashid Kapan (published in The Hindu newspaper), Balraj (little talent, sycophantic), Abhishek Hazra (later became art critic, ignored Raghava at art fairs), Ayyan (engineer, best draftsmanship in group). Raghava was 'the brat'-celebrity cartoonist, known all over Bangalore, had nothing to lose. Initially, they loved him. He was precocious, published, famous. He outgrew them quickly. Their verdict (never said to his face): self-centered, attention-seeking, megalomaniac. Raghava took it to heart and still carries the label at 44. This was the first organized rejection by peers-not teachers, but equals.\n\nCU active 1997-1998. Raghava dropped/expelled in 1999. The betrayal show (competing with Black Cadillac) was in 1998. Merged with cartoonists-unanimous-members-verdict.",
