    "psychological_note": null,
    "studio_note": null,
    "notes": "Shankar Mama offered the trip: if family paid airfare, he and Linda Aunty handled everything. Raghava overpacked with synthetic snow jacket from Commercial Street and thick leather boots. Linda Aunty asked airport police for his photo and showed him off everywhere-but with no stakes. 'I felt seen. Not needed. Just seen.' With Reggie Aunty and Sunder Uncle, he was given structure and belonging: assigned the role of spraying Windex on glass tabletops. This small job gave him purpose. They said 'Thanked God for your presence.' His existence was not a burden. This was the opposite of home.\n\nFOUNDATIONAL PATTERN: Official family withholds (parents can't afford, don't prioritize). Peripheral people give freely (Reggie, Sunder). Escape first proven possible. Also: the mechanism is forming-magic and performance simultaneously.",
