    "psychological_note": null,
    "studio_note": null,
    "notes": "Around 11th grade, mother became seriously ill. Drinking heavily, depressed, having affairs. Men would come and socialize with father. Father knew. Never addressed the alcoholism, the affairs, the children's coping. Never once said he saw Raghava struggling. Never apologized. When asked directly if he saw: 'Never.' His silence was not discipline. It was absence. This is the architecture reproduced: intermittent presence followed by long absence. Intense showing up (Algebra summer) followed by profound withdrawal (mother's crisis).\n\nThe father's refusal to see during crisis is the inverse of his 'seeing greatness' in the algebra summer. He sees greatness. He doesn't see need.",
