    "notes": "In one morning: discovered Cartoonists Unanimous had organized a competing group show same day/place without telling him (betrayal by peers). By this point, cumulative losses: Naseer gone (stolen, disappeared, promise kept); Karthik in America (had shamed him at Dartmouth); Kaesava in Australia; Mother drowning (alcoholism, affairs, crisis calls); Father unreachable (silence, absence, never asked what grade he was in). The structure of family was gone. The peer group was gone. The first love was gone. At 18, completely alone. This moment-the confluence of all losses-is what breaks something and births the mechanism.\n\nTHE CRUCIBLE: This convergence of losses is the birth moment of the mechanism. Act One ends here. The mechanism: when everything real is taken, become so bright performing that no one can look away.",
