    "notes": "An interactive children’s book, Pop-it allowed readers to experience unconventional family structures through vibrant illustrations and animations. The book used touchscreen technology to let children engage with and question traditional family norms. It won the Kirkus Book Award and was named one of the best books of 2011 by Kirkus Reviews for its original format and thought-provoking themes.",
